import handleError from '../src/handleError.ts';
import generateRenderingErrorMessage from '../src/generateRenderingErrorMessage.ts';
import type { ErrorOptions } from '../src/types/index.ts';

// Untyped JavaScript callers, such as the wrapper generated by the Rails `server_render_js` helper,
// pass whatever value was thrown straight through as `e`.
const optionsFor = (thrownValue: unknown, overrides: Partial<ErrorOptions> = {}): ErrorOptions => ({
  e: thrownValue as ErrorOptions['e'],
  jsCode: 'failingExpression()',
  serverSide: true,
  ...overrides,
});

const primitiveThrows: [description: string, thrownValue: unknown, expectedMessage: string][] = [
  ['null', null, 'null'],
  ['undefined', undefined, 'undefined'],
  ['a string', 'plain string failure', 'plain string failure'],
  ['a number', 42, '42'],
];

describe('generateRenderingErrorMessage', () => {
  it.each(primitiveThrows)(
    'shows the thrown value as the message when %s is thrown',
    (_description, thrownValue, expectedMessage) => {
      const msg = generateRenderingErrorMessage(optionsFor(thrownValue));

      expect(msg).toContain('Exception in rendering!');
      expect(msg).toContain(`Message: ${expectedMessage}`);
      expect(msg).toContain(`Error: ${expectedMessage}`);
    },
  );

  it('checks Render-Function mistakes without throwing when a component name is given', () => {
    const msg = generateRenderingErrorMessage(optionsFor(null, { name: 'MyComponent' }));

    expect(msg).toContain('Message: null');
  });

  it('keeps the message, stack, and location of thrown Error instances', () => {
    const error: ErrorOptions['e'] = new Error('boom');
    error.stack = 'Error: boom\n    at bundle.js:1:1';
    error.fileName = 'bundle.js';
    error.lineNumber = '1';

    const msg = generateRenderingErrorMessage(optionsFor(error));

    expect(msg).toContain('location: bundle.js:1');
    expect(msg).toContain('Message: boom');
    expect(msg).toContain('Error: boom\n    at bundle.js:1:1');
  });

  it('keeps the message and stack of thrown Error-like objects', () => {
    const msg = generateRenderingErrorMessage(
      optionsFor({ message: 'object failure', stack: 'Error: object failure\n    at app.js:2:3' }),
    );

    expect(msg).toContain('Message: object failure');
    expect(msg).toContain('Error: object failure\n    at app.js:2:3');
  });

  it('does not serialize the fields of a thrown plain object', () => {
    const msg = generateRenderingErrorMessage(optionsFor({ apiToken: 'secret-token' }));

    expect(msg).toContain('Exception in rendering!');
    expect(msg).not.toContain('secret-token');
  });

  it('returns the client-side placeholder for a non-Error throw', () => {
    expect(generateRenderingErrorMessage(optionsFor(null, { serverSide: false }))).toBe('undefined');
  });
});

describe('handleError', () => {
  it.each(primitiveThrows)(
    'renders the error HTML when %s is thrown',
    (_description, thrownValue, expectedMessage) => {
      const html = handleError(optionsFor(thrownValue));

      expect(html).toMatch(/^<pre>Exception in rendering!/);
      expect(html).toContain(`Message: ${expectedMessage}`);
    },
  );
});
